    {
      "id": "s1",
      "tag": "Apostrophe",
      "text": "When Douglass addresses \"you\" throughout the oration, he is directly apostrophizing the white Rochester audience seated before him, not a general readership.",
      "context": "\"What, to the American slave, is your 4th of July? I answer: a day that reveals to him... the gross injustice and cruelty to which he is the constant victim.\"",
      "correctSide": "right",
      "feedback": "The second-person address is a deliberate rhetorical confrontation — he names his auditors as complicit witnesses."
    },
    {
      "id": "s2",
      "tag": "Tone",
      "text": "The dominant tone of the passage is celebratory and conciliatory, matching the festive occasion of the Fourth.",
      "correctSide": "left",
      "feedback": "The tone is prophetic denunciation; the holiday is the foil he turns against the audience."
    },
    {
      "id": "s3",
      "tag": "Antithesis",
      "text": "The oration's central structural device is antithesis: the gap between America's stated ideals and the reality of slavery is staged as a series of sharp contrasts.",
      "correctSide": "right",
      "feedback": "\"This Fourth of July is yours, not mine. You may rejoice, I must mourn.\" — the contrast is the engine of the argument."
    },
    {
      "id": "s4",
      "tag": "Evidence",
      "text": "Douglass supports his indictment primarily with statistical tables of cotton exports rather than with moral and biblical appeals.",
      "correctSide": "left",
      "feedback": "The appeals are overwhelmingly ethical and scriptural — Jeremiah, Isaiah, and the language of sin and covenant."
    },
    {
      "id": "s5",
      "tag": "Irony",
      "text": "Douglass's praise of the Founders is sincere homage, offered to soften the audience before his criticism.",
      "correctSide": "left",
      "feedback": "It is strategic irony: honoring the Fathers is the lever that indicts their sons for betraying their own revolution."
    },
    {
      "id": "s6",
      "tag": "Audience",
      "text": "The speech was delivered in 1852 to a mostly white, abolitionist-sympathetic audience in Rochester, New York — a fact that shapes his use of \"you\" and \"we.\"",
      "correctSide": "right",
      "feedback": "The pronoun work tracks that split audience: he claims a \"we\" of the enslaved and addresses a \"you\" of the republic."
    },
    {
      "id": "s7",
      "tag": "Figurative language",
      "text": "The image of the nation's birthday as a revelry that exposes the slave's suffering functions as a figure of aporia — a staged inability to know what to say.",
      "correctSide": "left",
      "feedback": "It's irony and antithesis, not aporia: his position is painfully clear, not uncertain."
    },
    {
      "id": "s8",
      "tag": "Ethos",
      "text": "Douglass repeatedly builds ethos by acknowledging his own former status as an enslaved person, which authorizes his witness while complicating any charge of outside agitator.",
      "correctSide": "right",
      "feedback": "His lived experience is the credential — \"I have been a slave myself\" — grounding both ethos and pathos."
    }
